package oracle;
import java.io.*;import java.util.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;import core.game.world.map.Location;import core.game.node.entity.Entity;import core.worker.MajorUpdateWorker;
public class Support{
 static Map input;static Entity entity;static List<Object>events;static Map<String,Integer>calls;public static int ticks,packetTime;static int clockIndex;
 public static class Failure extends RuntimeException{String phase;Failure(String p){phase=p;}public void printStackTrace(){emit("exception",phase);}}
 static int n(Object o){return((Number)o).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}
 static Location loc(Object o){if(o==null)return null;List a=(List)o;return Location.create(n(a.get(0)),n(a.get(1)),n(a.get(2)));}
 static Object coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}
 public static void emit(String phase,Object...args){List<Object> row=new ArrayList<>();row.add(phase);row.addAll(Arrays.asList(args));events.add(row);int count=calls.merge(phase,1,Integer::sum);for(Object h:(List)input.getOrDefault("hooks",Collections.emptyList())){Map hook=(Map)h;if(phase.equals(hook.get("event"))&&count==v(hook,"at",1))for(Object a:(List)hook.get("actions"))act((Map)a);}if(count==v((Map)input.getOrDefault("failures",Collections.emptyMap()),phase,-1))throw new Failure(phase);}
 public static long clock(){List a=(List)input.getOrDefault("clock",Collections.emptyList());long value=clockIndex<a.size()?((Number)a.get(clockIndex)).longValue():clockIndex;clockIndex++;emit("clock",value);return value;}
 public static void walk(){emit("walking");if(input.containsKey("walkTo"))entity.location=loc(input.get("walkTo"));}
 public static class Phase{String name;public Phase(String n){name=n;}public void update(){emit(name);}public void updateAll(){emit(name);}public void tick(){emit(name);}}
 public static class Sequence{public void start(){emit("start");if(Boolean.TRUE.equals(input.get("doEntity")))entity.tick();}public void run(){emit("run");}public void end(){emit("end");}}
 static void act(Map a){switch((String)a.get("op")){case"handle":new MajorUpdateWorker().handleTickActions(Boolean.TRUE.equals(a.get("skip")));break;case"entity":entity.tick();break;case"set":if(a.containsKey("location"))entity.location=loc(a.get("location"));break;case"mutate":if(entity.location!=null){Location l=loc(a.get("location"));entity.location.setX(l.getX());entity.location.setY(l.getY());entity.location.setZ(l.getZ());}break;default:throw new IllegalArgumentException();}}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);entity=new Entity();entity.location=loc(input.getOrDefault("location",Arrays.asList(3207L,3216L,0L)));ticks=v(input,"ticks",0);packetTime=0;clockIndex=0;events=new ArrayList<>();calls=new HashMap<>();List<Object>states=new ArrayList<>();for(Object a:(List)input.get("actions")){events.clear();String error=null;try{act((Map)a);}catch(Failure e){error=e.phase;}Map<String,Object>state=new TreeMap<>();state.put("location",coord(entity.location));state.put("ticks",ticks);state.put("packetTime",packetTime);state.put("clockIndex",clockIndex);state.put("events",new ArrayList<>(events));state.put("error",error);states.add(state);}input.put("expected",states);System.out.println(JSONValue.toJSONString(input));}}}
}
